use std::collections::HashMap;
use std::sync::{OnceLock, RwLock};
type Factory = fn() -> Box<dyn Plugin>;
fn registry() -> &'static RwLock<HashMap<&'static str, Factory>> {
    static REGISTRY: OnceLock<RwLock<HashMap<&'static str, Factory>>> =
        OnceLock::new();
    REGISTRY.get_or_init(|| RwLock::new(HashMap::new()))
}
pub fn register(name: &'static str, f: Factory) -> Result<(), &'static str> {
    let mut map = registry().write().unwrap();
    if map.insert(name, f).is_some() { return Err("duplicate registration"); }
    Ok(())
}

