use std::any::{Any, TypeId};
use std::collections::HashMap;
use std::sync::{Arc, OnceLock, RwLock};

type AnyService = Arc<dyn Any + Send + Sync>;

fn services() -> &'static RwLock<HashMap<TypeId, AnyService>> {
    static SERVICES: OnceLock<RwLock<HashMap<TypeId, AnyService>>> =
        OnceLock::new();
    SERVICES.get_or_init(|| RwLock::new(HashMap::new()))
}

pub fn put<T: Any + Send + Sync>(service: T) {
    services().write().unwrap().insert(TypeId::of::<T>(), Arc::new(service));
}
